// Synthetic coverage preview. No live historical query or assignment is performed.
function estimatedCoverage(p){
 const users=100,cycles=p.evaluation==='Daily'?14:p.evaluation==='Weekly'?2:1,crossed=p.rows.map(()=>new Set()),earners=new Set();let payout=0;
 for(let user=0;user<users;user++)for(let cycle=0;cycle<cycles;cycle++){
  const metrics={...p.metrics};for(const [j,key] of [...new Set([p.primary,...p.others,p.payout])].entries()){
   const target=Math.max(1,...p.rows.map(r=>Number(r.targets[key])||0),Number(p.metrics[key])||0),factor=((user*17+cycle*11+j*23)%125)/100;
   metrics[key]=measure(key).integer?Math.floor(target*factor):Number((target*factor).toFixed(2));
  }
  const result=calculate({...p,metrics});payout+=result.total;if(result.total>0)earners.add(user);result.matches.forEach((match,i)=>{if(match)crossed[i].add(user)});
 }
 return {users,earners:earners.size,payout,crossed:crossed.map(x=>x.size),cycles};
}
function openEstimatedCoverage(p){
 const error=programValidation(p);if(error){toast(error);return}
 const result=estimatedCoverage(p),today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),end=new Date(today+'T00:00:00Z'),start=new Date(end);end.setUTCDate(end.getUTCDate()-1);start.setUTCDate(start.getUTCDate()-14);
 const date=d=>d.toLocaleDateString('en-IN',{timeZone:'UTC',day:'numeric',month:'short',year:'numeric'}),dialog=document.getElementById('fieldDialog');dialog.className='details-dialog';dialog.setAttribute('aria-labelledby','coverageTitle');
 dialog.innerHTML=`<div class="panel-head"><div><h2 id="coverageTitle">Estimated coverage</h2><p class="quiet">${esc(p.name)}</p></div><button class="close" id="closeEstimatedCoverage" aria-label="Close estimated coverage">×</button></div><div class="dialogbody"><p><strong>Last 14 days</strong> · ${date(start)} – ${date(end)}</p><div class="notice">Sample estimates only. No historical data is connected. The preview assumes 100 eligible users; entity-filter coverage is not verified.</div><div class="grid"><section class="panel panel-body"><span>Users covered</span><h2>${result.users}</h2><small>Unique sample users</small></section><section class="panel panel-body"><span>Estimated payout</span><h2>${currency(result.payout)}</h2><small>Includes the applicable per-user cap</small></section></div><p class="quiet">${result.earners} sample users earn an incentive. ${esc(p.evaluation==='Custom'?'Programme duration':p.evaluation)} evaluation.</p><h3>Users expected to cross each slab</h3><div class="tablewrap"><table><thead><tr><th>Slab</th><th>Required targets</th><th>Users</th><th>% of covered users</th></tr></thead><tbody>${p.rows.map((r,i)=>`<tr><td>${i+1}</td><td>${[p.primary,...p.others].map(k=>esc(measure(k).label)+' ≥ '+esc(r.targets[k])).join('<br>AND ')}</td><td>${result.crossed[i]}</td><td>${(result.crossed[i]/result.users*100).toFixed(1)}%</td></tr>`).join('')}</tbody></table></div><p class="quiet">A user crosses a slab only when all its targets are met in the same evaluation period. Each user is counted once per slab across the window; percentages are cumulative and do not add up to 100%.</p><p class="quiet">${p.evaluation==='Daily'?'Illustrates 14 daily evaluations.':p.evaluation==='Weekly'?'Illustrates two complete weekly evaluations; actual dates must align to the programme’s weekly boundaries.':'The 14-day window may not contain a complete evaluation period. The amount shown illustrates one sample evaluation, not a full-period historical estimate or forecast.'}</p><p class="quiet">Uses the current unsaved reward rules, sample measurements and field-filter checks. Live coverage will require eligible entity data and complete evaluation windows.</p><div class="form-actions"><button class="button primary" id="backToIncentive">Back to configuration</button></div></div>`;
 if(!dialog.open)dialog.showModal();document.getElementById('closeEstimatedCoverage').onclick=document.getElementById('backToIncentive').onclick=()=>dialog.close();
}
